  rw_cells asegs m (A + size) (CookieCells j7) ->
  0 < A -> A mod 8 = 0 -> 0 <= size -> size mod 8 = 0 -> A + size + 15 <= aceil ->
  addressable m A (size + 15) ->
  stk asegs m lo (bv_unsigned sp) -> lo + 16 <= bv_unsigned sp -> aceil <= lo ->
  mem_inv asegs m -> ACONST m ->
  evt asegs (dealloc_seg_post ra sp gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc A size lo m)
